// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _recipient, uint _valueToSend, uint _depositValue) public {
        vm.assume(_recipient != address(0));
        vm.assume(_recipient != address(c));
        vm.assume(_valueToSend <= address(c).balance);
        vm.assume(_depositValue <= type(uint).max / 10); // avoid overflow
        // first deposit some eth via fallback to increase contract balance
        vm.deal(address(this), _depositValue);
        (bool successDeposit, ) = address(c).call{value: _depositValue}("");
        require(successDeposit);

        // now call sendMoney with given parameters
        (bool successSend, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", _recipient, _valueToSend));
        if (successSend) {
            // rule: after a successful sendMoney, the contract balance must be exactly (balance before call) - _valueToSend
            // but because the buggy withdraw uses call instead of transfer, the rule may break.
            // For the reference, after sendMoney, the balance is correct.
            // We assert that the contract balance equals the original deposit value minus what was sent.
            // However, since sendMoney itself may revert if call fails, we only check when successSend is true.
            // Actually, the bug is in withdraw, not sendMoney. We need to trigger withdraw via sendMoney? No, the difference says after sendMoney completes, the withdraw function returns different values.
            // The rule: after a sendMoney call, calling withdrawAll should work if the balance is nonzero.
            uint balanceBefore = address(c).balance;
            // trigger withdrawAll (which calls the buggy withdraw)
            vm.prank(c.owner());
            (bool successWithdraw, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
            if (successWithdraw) {
                // if withdraw succeeded, contract balance should be 0
                assertTrue(address(c).balance == 0);
            } else {
                // if withdraw reverted, contract balance should be unchanged from before withdraw attempt
                assertTrue(address(c).balance == balanceBefore);
            }
        }
    }
}

